921	    fn parse_oid(content: &[u8]) -> Result<Vec<Arc>, String> {
922	        if content.is_empty() {
923	            return Err("empty OID".to_string());
924	        }
925	        let mut arcs = Vec::new();
926	        // The first subidentifier encodes the first two arcs as
927	        // 40*first + second and is itself a base-128 quantity, so it can
928	        // span multiple content bytes (e.g. 2.999 encodes as 0x88 0x37) and
929	        // can exceed any machine integer width when the second arc is huge.
930	        let mut i = 0;
931	        let first = read_oid_arc(content, &mut i)?;
932	        match first.as_u64() {
933	            Some(v @ 0..=39) => {
934	                arcs.push(Arc::from_u64(0));
935	                arcs.push(Arc::from_u64(v));
936	            }
937	            Some(v @ 40..=79) => {
938	                arcs.push(Arc::from_u64(1));
939	                arcs.push(Arc::from_u64(v - 40));
940	            }
941	            _ => {
942	                // First arc 2: the second arc is the subidentifier minus 80,
943	                // kept at full precision even when it needs more than 64
944	                // bits.
945	                let mut second = first;
946	                second.sub_u32(80);
947	                arcs.push(Arc::from_u64(2));
948	                arcs.push(second);
949	            }
950	        }
951	        while i < content.len() {
952	            arcs.push(read_oid_arc(content, &mut i)?);
953	        }
954	        Ok(arcs)
955	    }
956	
957	    /// Read one base-128 subidentifier starting at `*i`. Rejects trailing
958	    /// continuation bytes and non-minimal encodings; the value itself is
959	    /// unbounded and kept exactly.
960	    fn read_oid_arc(content: &[u8], i: &mut usize) -> Result<Arc, String> {
961	        let start = *i;
962	        let mut value = Arc { limbs: Vec::new() };
963	        loop {
964	            let b = *content
965	                .get(*i)
966	                .ok_or_else(|| "truncated OID arc".to_string())?;
967	            value.mul_add_128((b & 0x7F) as u32);
968	            *i += 1;
969	            if b & 0x80 == 0 {
970	                break;
971	            }
972	        }
973	        if *i - start > 1 && content[start] == 0x80 {
974	            return Err("non-minimal OID arc encoding".to_string());
975	        }
976	        Ok(value)
977	    }
978	
979	    fn arcs_to_string(arcs: &[Arc]) -> String {
980	        arcs.iter()
981	            .map(Arc::to_decimal)
982	            .collect::<Vec<_>>()
983	            .join(".")
984	    }
