986	    fn oid_short_name(arcs: &[Arc]) -> Option<&'static str> {
987	        // The known names all live far below 2^64; any arc that does not fit
988	        // a u64 cannot match, which falls out of the conversion for free.
989	        let small: Option<Vec<u64>> = arcs.iter().map(Arc::as_u64).collect();
990	        // X.520 / X.521 (2.5.4.*) and the commonly used LDAP/PKCS names.
991	        let name = match small.as_deref() {
992	            Some([2, 5, 4, 3]) => "CN",
993	            Some([2, 5, 4, 4]) => "SN",
994	            Some([2, 5, 4, 5]) => "serialNumber",
995	            Some([2, 5, 4, 6]) => "C",
996	            Some([2, 5, 4, 7]) => "L",
997	            Some([2, 5, 4, 8]) => "ST",
998	            Some([2, 5, 4, 9]) => "STREET",
999	            Some([2, 5, 4, 10]) => "O",
1000	            Some([2, 5, 4, 11]) => "OU",
1001	            Some([2, 5, 4, 12]) => "title",
1002	            Some([2, 5, 4, 17]) => "postalAddress",
1003	            Some([2, 5, 4, 18]) => "postalCode",
1004	            Some([2, 5, 4, 20]) => "telephoneNumber",
1005	            Some([2, 5, 4, 42]) => "givenName",
1006	            Some([2, 5, 4, 43]) => "initials",
1007	            Some([2, 5, 4, 44]) => "generationQualifier",
1008	            Some([2, 5, 4, 46]) => "dnQualifier",
1009	            Some([2, 5, 4, 65]) => "pseudonym",
1010	            Some([0, 9, 2342, 19200300, 100, 1, 1]) => "UID",
1011	            Some([0, 9, 2342, 19200300, 100, 1, 25]) => "DC",
1012	            Some([1, 2, 840, 113549, 1, 9, 1]) => "emailAddress",
1013	            _ => return None,
1014	        };
1015	        Some(name)
