145	#[test]
146	fn outer_algorithm_with_truncated_oid_arcs_is_rejected() {
147	    // 06 01 88: a continuation byte promises another base-128 byte that the
148	    // (correctly sized) enclosing SEQUENCE never provides.
149	    let broken = seq(&raw_tlv(0x06, &[0x01], &[0x88]));
150	    let good = alg_with_null_params(SHA256_WITH_RSA);
151	    let (out, _cert) = run_inspect("outer-oid-trunc", &build_cert(&broken, &good));
152	    assert_invalid_at(&out, "outer signatureAlgorithm");
153	}
