155	#[test]
156	fn outer_algorithm_with_truncated_oid_tlv_is_rejected() {
157	    // The OID TLV header announces three content bytes but the SEQUENCE only
158	    // contains two: a half-read OID must fail inside the outer identifier.
159	    let broken = seq(&concat(&[&[0x06, 0x03, 0x2A, 0x03]]));
160	    let good = alg_with_null_params(SHA256_WITH_RSA);
161	    let (out, _cert) = run_inspect("outer-oid-tlv-trunc", &build_cert(&broken, &good));
162	    assert_invalid_at(&out, "outer signatureAlgorithm");
163	}
