165	#[test]
166	fn outer_algorithm_with_nonminimal_oid_encoding_is_rejected() {
167	    // Arc value 1 encoded as 0x80 0x01 (leading 0x80 continuation byte) is
168	    // not the shortest base-128 encoding and is invalid DER.
169	    let broken = seq(&raw_tlv(0x06, &[0x02], &[0x80, 0x01]));
170	    let good = alg_with_null_params(SHA256_WITH_RSA);
171	    let (out, _cert) = run_inspect("outer-oid-nonmin", &build_cert(&broken, &good));
172	    assert_invalid_at(&out, "outer signatureAlgorithm");
