175	#[test]
176	fn outer_algorithm_with_truncated_parameter_is_rejected() {
177	    // A parameter TLV announcing five content bytes with only three present
178	    // cannot be skipped over.
179	    let truncated_params = raw_tlv(0x04, &[0x05], b"abc");
180	    let broken = seq(&concat(&[&oid(SHA256_WITH_RSA), &truncated_params]));
181	    let good = alg_with_null_params(SHA256_WITH_RSA);
182	    let (out, _cert) = run_inspect("outer-param-trunc", &build_cert(&broken, &good));
183	    assert_invalid_at(&out, "outer signatureAlgorithm");
