#!/usr/bin/env python3
"""Generate the two example DER certificates for the README signature
algorithm section.

cert_match_null.der: outer signatureAlgorithm and the copy inside
tbsCertificate both carry sha256WithRSAEncryption OID + explicit NULL.

cert_param_mismatch.der: identical except the tbsCertificate copy omits
its parameters (OID only), so the two well-formed copies disagree.
"""

SHA256_WITH_RSA = [1, 2, 840, 113549, 1, 1, 11]


def tlv(tag, content):
    n = len(content)
    if n < 0x80:
        length = bytes([n])
    else:
        body = []
        v = n
        while v:
            body.append(v & 0xFF)
            v >>= 8
        body.reverse()
        length = bytes([0x80 | len(body)]) + bytes(body)
    return bytes([tag]) + length + content


def seq(content):
    return tlv(0x30, content)


def oid(arcs):
    def arc(value):
        out = [value % 128]
        value //= 128
        while value:
            out.append(0x80 | (value % 128))
            value //= 128
        out.reverse()
        return bytes(out)

    content = arc(arcs[0] * 40 + arcs[1])
    for a in arcs[2:]:
        content += arc(a)
    return tlv(0x06, content)


def alg_with_null(arcs):
    # OID then explicit NULL parameter
    return seq(oid(arcs) + tlv(0x05, b""))


def alg_oid_only(arcs):
    return seq(oid(arcs))


def simple_cn(cn):
    atv = seq(oid([2, 5, 4, 3]) + tlv(0x0C, cn.encode()))
    return seq(tlv(0x31, atv))


def build_cert(outer_alg, tbs_alg, path):
    serial = tlv(0x02, bytes([0x0E, 0x8A, 0x4C, 0x2F, 0x9B, 0x17, 0xD6, 0x03]))
    validity = seq(tlv(0x17, b"260115093000Z") + tlv(0x17, b"270115093000Z"))
    subject = simple_cn("example.com")
    issuer = simple_cn("Test CA")
    # subjectPublicKeyInfo: rsaEncryption OID + NULL, one-byte placeholder key
    spki_alg = seq(oid([1, 2, 840, 113549, 1, 1, 1]) + tlv(0x05, b""))
    spki = seq(spki_alg + tlv(0x03, bytes([0x00, 0x01, 0x00])))
    tbs = seq(serial + tbs_alg + issuer + validity + subject + spki)
    cert = seq(tbs + outer_alg + tlv(0x03, bytes([0x00])))
    with open(path, "wb") as f:
        f.write(cert)


build_cert(
    alg_with_null(SHA256_WITH_RSA),
    alg_with_null(SHA256_WITH_RSA),
    "/tmp/cert_match_null.der",
)
build_cert(
    alg_with_null(SHA256_WITH_RSA),
    alg_oid_only(SHA256_WITH_RSA),
    "/tmp/cert_param_mismatch.der",
)
print("written")

